<div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2>Servicio técnico</h2><p class="text-muted mb-0">Consulta y solicita asistencia para tus equipos.</p></div><a class="btn btn-primary" href="<?= base_url('cliente/servicio_tecnico/solicitar') ?>">Solicitar servicio</a></div><?php if ($this->session->flashdata('exito')): ?><div class="alert alert-success"><?= html_escape($this->session->flashdata('exito')) ?></div><?php endif ?><?php if ($this->session->flashdata('error')): ?><div class="alert alert-danger"><?= html_escape($this->session->flashdata('error')) ?></div><?php endif ?><?php if (!empty($servicios)): ?><div class="table-responsive bg-white rounded shadow-sm"><table class="table align-middle mb-0"><thead><tr><th>Solicitud</th><th>Equipo</th><th>Ingreso</th><th>Estado</th><th>Técnico</th><th></th></tr></thead><tbody><?php foreach ($servicios as $servicio): ?><tr><td>#<?= (int)$servicio->id_mantenimiento ?></td><td><?= html_escape($servicio->nombre_equipo) ?></td><td><?= date('d/m/Y',strtotime($servicio->fecha_ingreso)) ?></td><td><?= html_escape($servicio->estado_actual ?: 'Pendiente de asignación') ?></td><td><?= !empty($servicio->tecnico_nombre) ? html_escape($servicio->tecnico_nombre.' '.$servicio->tecnico_apellido) : 'Sin asignar' ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= base_url('cliente/servicio_tecnico/detalle/'.$servicio->id_mantenimiento) ?>">Ver</a></td></tr><?php endforeach ?></tbody></table></div><?php else: ?><div class="alert alert-info">Aún no tienes solicitudes de servicio.</div><?php endif ?></div>
